translations={}
for line in rows.splitlines():
    values=line.split('|');assert len(values)==8,values
    translations[values[0]]=values[1:]
translations['2D / 3D']=['2D / 3D']*7
translations[' ply']=[' medias jugadas',' demi-coups',' Halbzüge',' meios-lances',' semimosse',' halve zetten',' półruchów']
translations['Engine Arena — 1.2.0']=['Engine Arena — 1.2.0']*7
translations['Engine Arena — 1.2.1']=['Engine Arena — 1.2.1']*7
translations['Engine Arena — 1.2.2']=['Engine Arena — 1.2.2']*7
translations['Engine Arena — 1.2.10']=['Engine Arena — 1.2.10']*7
translations['3D · 1849 Staunton']=['3D · Staunton 1849']*7
for i,code in enumerate(['es','fr','de','pt','it','nl','pl']):
    path=folder/(code+'.json');data=json.loads(path.read_text(encoding='utf-8'))
    for key,values in translations.items():
        if key in sources:data['messages'][key]=values[i]
    missing=[key for key in sources if key not in data['messages']]
    assert not missing,(code,missing)
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(folder/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Workflow translations updated in seven languages.')
